package riscv

import (
	"testing"

	"gno.land/p/moul/x/vm/vmkit/v0"
	"gno.land/p/nt/uassert/v0"
)

// The measurement the design issue set a kill criterion against: if an RV32I
// instruction costs more than roughly 15k cycles after the bf ladder's tricks,
// a RISC-V guest runs ~200k instructions per block, which is a token transfer
// and not a program a Rust programmer would write without thinking about it.
//
// The loop is arithmetic and branches only, no syscalls and no memory beyond
// the fetch, so it measures the decode-and-dispatch path rather than the host.

// li loads a full 32-bit constant, because addi cannot: its immediate is 12
// bits SIGN EXTENDED, so addi(rd, x0, 4000) loads -96 and a loop counting up to
// it never terminates. That is not hypothetical, it hung this benchmark for two
// days. The +0x800 pre-bias is the standard correction: it cancels the sign
// extension addi is about to apply to the low half.
func li(rd, v uint32) []uint32 {
	return []uint32{
		lui(rd, (v+0x800)&0xFFFFF000),
		addi(rd, rd, v&0xFFF),
	}
}

func lui(rd, imm uint32) uint32 { return uType(imm, rd, opLUI) }

// benchProg counts x6 up to x8 in a 4-instruction loop, then exits.
func benchProg(n uint32) []uint32 {
	prog := li(8, n) // x8 = n, the loop bound
	prog = append(prog,
		addi(5, 0, 0), // sum = 0
		addi(6, 0, 0), // i   = 0
		// loop:
		add(5, 5, 6),      // sum += i
		addi(6, 6, 1),     // i++
		addi(7, 0, 0),     // filler, keeps the loop a round 4 instructions
		bne(6, 8, 0x1FF4), // -12, while i != x8
	)
	return append(prog, exitWith()...)
}

// benchInstrs is how many instructions benchProg(n) executes: 4 setup (li is
// two), 4 per iteration including the branch, 2 to exit.
func benchInstrs(n int64) int64 { return 4 + 4*n + 2 }

// runBench returns the instruction count the machine charged itself. The fuel
// cap is ten times what the program should need: a mis-encoded immediate turns
// an unmetered run into an infinite loop with no test output, so the budget is
// what makes a bad encoding fail in a second instead of hanging the suite.
func runBench(t *testing.T, n uint32) int64 {
	t.Helper()
	m, err := NewMachine(asm(benchProg(n)), entry)
	uassert.NoError(t, err)
	if m == nil {
		return 0
	}
	used, status := m.Step(vmkit.NewTestHost(), benchInstrs(int64(n))*10)
	uassert.Equal(t, "halted", status.String())
	return used
}

// One test per size, so `gno test -print-runtime-metrics` prints one cycle
// count each and the slope cancels the fixed per-test overhead. The README
// quotes the result.

func TestBenchRV32I1000(t *testing.T) {
	uassert.Equal(t, benchInstrs(1000), runBench(t, 1000))
}

func TestBenchRV32I4000(t *testing.T) {
	uassert.Equal(t, benchInstrs(4000), runBench(t, 4000))
}

// li has to survive the sign-extension boundary in both directions, or the two
// sizes above are not measuring the loop counts they claim to.
func TestLoadImmediateSpansTheSignBoundary(t *testing.T) {
	for _, v := range []uint32{0, 1, 0x7FF, 0x800, 1000, 4000, 0x7FFFFFFF, 0xFFFFFFFF} {
		prog := append(li(5, v), exitWith()...)
		m, err := NewMachine(asm(prog), entry)
		uassert.NoError(t, err)
		if m == nil {
			continue
		}
		_, status := m.Step(vmkit.NewTestHost(), vmkit.Unmetered)
		uassert.Equal(t, "halted", status.String())
		uassert.Equal(t, uint64(v), uint64(m.reg[5]))
	}
}

// Predecoding is paid once per load, and a realm loads a machine on every
// transaction that resumes one. So the saving on the dispatch loop is only
// real if this side of the trade is small against the instructions the slice
// then executes. Two sizes again, so the slope is per word.
func benchImage(words int) []byte {
	img := make([]byte, words*4)
	inst := addi(5, 5, 1)
	for i := 0; i < words; i++ {
		img[i*4] = byte(inst)
		img[i*4+1] = byte(inst >> 8)
		img[i*4+2] = byte(inst >> 16)
		img[i*4+3] = byte(inst >> 24)
	}
	return img
}

func TestBenchPredecode1000(t *testing.T) {
	c := predecode(entry, benchImage(1000))
	uassert.Equal(t, uint64(1000), uint64(c.words))
}

func TestBenchPredecode4000(t *testing.T) {
	c := predecode(entry, benchImage(4000))
	uassert.Equal(t, uint64(4000), uint64(c.words))
}

// The control, so the slope above is predecode and not the loop that builds
// the image.
func TestBenchImageOnly1000(t *testing.T) {
	uassert.Equal(t, 4000, len(benchImage(1000)))
}

func TestBenchImageOnly4000(t *testing.T) {
	uassert.Equal(t, 16000, len(benchImage(4000)))
}

package riscv

import (
	"testing"

	"gno.land/p/moul/x/vm/vmkit/v0"
	"gno.land/p/nt/uassert/v0"
)

// A guest compiled by a real compiler, which is the only test here that was
// not written by the same person who wrote the emulator.
//
// The image is guests.gno's, built from tools/riscv-guests/fnv by clang. It
// exercises what hand-written tests do not: a real function prologue spilling
// ra and s0 to a stack the host set up, .bss addressed far above a read-only
// text segment, LLVM's constant materialization through lui/addi pairs, and
// MUL in an inner loop.

// The expected hashes come from an independent FNV-1a, not from this VM.
func TestClangCompiledGuest(t *testing.T) {
	cases := []struct {
		in   string
		want string
	}{
		{"", "811c9dc5"},
		{"a", "e40c292c"},
		{"Hello", "f55c314b"},
		{"gno.land", "fb7ffba0"},
	}
	for _, c := range cases {
		m, err := NewMachine(GuestFNV(), entry)
		uassert.NoError(t, err)
		if m == nil {
			continue
		}
		h := vmkit.NewTestHost().WithInput([]byte(c.in))
		_, status := m.Step(h, vmkit.Unmetered)
		uassert.Equal(t, "halted", status.String(), "input "+c.in+": "+m.Trap())
		uassert.Equal(t, c.want, string(h.Out()), "fnv1a of "+c.in)
	}
}

// Compiled code pauses and resumes like anything else. This is the property a
// realm depends on, run against output a compiler produced rather than against
// a loop written to be sliceable.
func TestClangGuestSurvivesSlicing(t *testing.T) {
	image := GuestFNV()
	h := vmkit.NewTestHost().WithInput([]byte("gno.land"))

	sliced, err := NewMachine(image, entry)
	uassert.NoError(t, err)
	status := vmkit.Running
	slices := 0
	for i := 0; i < 500 && status == vmkit.Running; i++ {
		var fresh Machine
		uassert.NoError(t, fresh.Restore(sliced.Snapshot()))
		_, status = fresh.Step(h, 3)
		sliced = &fresh
		slices++
	}
	uassert.Equal(t, "halted", status.String())
	uassert.True(t, slices > 10, "a sliced run must actually have been sliced")
	uassert.Equal(t, "fb7ffba0", string(h.Out()))
}

// The guest writes its globals at 0x40000, which the linker script put well
// above the text segment on purpose. If it had put them adjacent, W xor X
// would trap on the first store, so this is the test that the memory layout
// the toolchain was told to use is the one the host actually provides.
func TestClangGuestWritesAboveItsText(t *testing.T) {
	m, err := NewMachine(GuestFNV(), entry)
	uassert.NoError(t, err)
	h := vmkit.NewTestHost().WithInput([]byte("gno.land"))
	_, status := m.Step(h, vmkit.Unmetered)
	uassert.Equal(t, "halted", status.String())

	// The text pages, the .bss page at 0x40000, and the stack page at the top.
	uassert.True(t, m.Memory().DirtyPages() >= 3,
		"the guest must have written outside its text segment")
	uassert.True(t, m.Memory().DirtyPages() <= 8,
		"a 196-byte program must not have dirtied the address space")
}

// Image is what every caller uses to turn words into a program, so a byte
// order mistake here would look like a decoder bug everywhere else.
func TestImageIsLittleEndian(t *testing.T) {
	b := Image([]uint32{0x04030201, 0xFF000000})
	uassert.Equal(t, 8, len(b))
	uassert.Equal(t, uint64(0x01), uint64(b[0]))
	uassert.Equal(t, uint64(0x04), uint64(b[3]))
	uassert.Equal(t, uint64(0x00), uint64(b[4]))
	uassert.Equal(t, uint64(0xFF), uint64(b[7]))

	// And it agrees with the assembler the other tests use.
	words := []uint32{addi(5, 0, 1), ecall()}
	a, i := asm(words), Image(words)
	uassert.Equal(t, len(a), len(i))
	for k := range a {
		uassert.Equal(t, uint64(a[k]), uint64(i[k]))
	}
}

// GuestFNV must not hand out a slice a caller can scribble on, because the
// next caller gets the same program.
func TestGuestFNVIsACopy(t *testing.T) {
	a := GuestFNV()
	a[0] = 0xFF
	b := GuestFNV()
	uassert.False(t, b[0] == 0xFF, "GuestFNV must return a fresh image each call")
}

package riscv

// RV32 instruction decode: bit fields, not a parser.
//
// Every instruction is exactly 32 bits and the opcode is the low 7. The rest is
// slicing: which fields exist depends on the format, and there are six formats.
// This file is only the slicing; exec.gno decides what the fields mean.

// Instruction formats. Named as the spec names them.
const (
	opLUI    = 0x37
	opAUIPC  = 0x17
	opJAL    = 0x6F
	opJALR   = 0x67
	opBranch = 0x63
	opLoad   = 0x03
	opStore  = 0x23
	opImm    = 0x13
	opReg    = 0x33
	opSystem = 0x73
	opFence  = 0x0F
)

// opcode returns the low 7 bits.
func opcode(inst uint32) uint32 { return inst & 0x7F }

// rd, rs1 and rs2 are register selectors, 5 bits each, always in the same place
// when the format has them.
func rd(inst uint32) uint32  { return (inst >> 7) & 0x1F }
func rs1(inst uint32) uint32 { return (inst >> 15) & 0x1F }
func rs2(inst uint32) uint32 { return (inst >> 20) & 0x1F }

// funct3 and funct7 narrow an opcode to an operation.
func funct3(inst uint32) uint32 { return (inst >> 12) & 0x7 }
func funct7(inst uint32) uint32 { return inst >> 25 }

// The immediates. Each format scatters the bits differently, and every one of
// them is SIGN EXTENDED from its top bit: RISC-V has no zero-extended immediate
// in the base set, and getting that wrong is the classic decoder bug because
// small positive programs still work.
//
// The shift-right-on-int32 idiom is the sign extension: Go defines >> on a
// signed type as arithmetic.

// immI is the 12-bit immediate of I-type (loads, ALU-immediate, JALR, ECALL).
func immI(inst uint32) uint32 { return uint32(int32(inst) >> 20) }

// immS is S-type (stores), split across two fields.
func immS(inst uint32) uint32 {
	return uint32(int32(inst)>>25<<5) | ((inst >> 7) & 0x1F)
}

// immB is B-type (branches): S-type with the bits rotated, and bit 0 always
// zero because a branch target is 2-byte aligned.
func immB(inst uint32) uint32 {
	imm := uint32(int32(inst)>>31) << 12 // sign, bit 12
	imm |= ((inst >> 7) & 0x1) << 11     // bit 11
	imm |= ((inst >> 25) & 0x3F) << 5    // bits 10:5
	imm |= ((inst >> 8) & 0xF) << 1      // bits 4:1
	return imm
}

// immU is U-type (LUI, AUIPC): the top 20 bits, already in place.
func immU(inst uint32) uint32 { return inst & 0xFFFFF000 }

// immJ is J-type (JAL), the most scattered of the six.
func immJ(inst uint32) uint32 {
	imm := uint32(int32(inst)>>31) << 20 // sign, bit 20
	imm |= ((inst >> 12) & 0xFF) << 12   // bits 19:12
	imm |= ((inst >> 20) & 0x1) << 11    // bit 11
	imm |= ((inst >> 21) & 0x3FF) << 1   // bits 10:1
	return imm
}

package riscv

import (
	"testing"

	"gno.land/p/nt/uassert/v0"
)

// jal is only needed to exercise immJ, the one format no program in
// riscv_test.gno reaches for.
func jal(rd, imm uint32) uint32 { return jType(imm, rd, opJAL) }

// The assembler in riscv_test.gno and the decoders here were written from the
// spec independently, so encoding a known field and reading it back is a real
// cross-check rather than a tautology: a field in the wrong place fails unless
// both files put it in the same wrong place.
func TestDecodeRoundTripsTheAssembler(t *testing.T) {
	inst := add(5, 6, 7)
	uassert.Equal(t, uint64(opReg), uint64(opcode(inst)))
	uassert.Equal(t, uint64(5), uint64(rd(inst)))
	uassert.Equal(t, uint64(6), uint64(rs1(inst)))
	uassert.Equal(t, uint64(7), uint64(rs2(inst)))
	uassert.Equal(t, uint64(0), uint64(funct3(inst)))
	uassert.Equal(t, uint64(0), uint64(funct7(inst)))
	uassert.Equal(t, uint64(0x20), uint64(funct7(sub(5, 6, 7))))
	uassert.Equal(t, uint64(0x01), uint64(funct7(mul(5, 6, 7))))
}

// Every immediate in the base set is sign extended from its own top bit, and
// the top bit is in a different place in each of the five formats. These are
// the boundary values: the largest positive, the value one past it that must
// come back negative, and all-ones for minus one.
func TestImmediatesSignExtend(t *testing.T) {
	// I-type, 12 bits.
	uassert.Equal(t, uint64(0x7FF), uint64(immI(addi(1, 2, 0x7FF))))
	uassert.Equal(t, uint64(0xFFFFF800), uint64(immI(addi(1, 2, 0x800))))
	uassert.Equal(t, uint64(0xFFFFFFFF), uint64(immI(addi(1, 2, 0xFFF))))

	// S-type, 12 bits split across two fields.
	uassert.Equal(t, uint64(0x7FF), uint64(immS(sw(3, 4, 0x7FF))))
	uassert.Equal(t, uint64(0xFFFFF800), uint64(immS(sw(3, 4, 0x800))))
	uassert.Equal(t, uint64(0xFFFFFFFF), uint64(immS(sw(3, 4, 0xFFF))))

	// B-type, 13 bits with bit 0 always zero. -12 is the encoding the
	// benchmark's loop branch uses, and getting its width wrong is what makes
	// a backward branch jump forward instead.
	uassert.Equal(t, uint64(0x7FE), uint64(immB(bne(1, 2, 0x7FE))))
	uassert.Equal(t, uint64(0xFFFFF000), uint64(immB(bne(1, 2, 0x1000))))
	uassert.Equal(t, uint64(0xFFFFFFF4), uint64(immB(bne(1, 2, 0x1FF4))))

	// U-type is the only one that is not sign extended, because it is already
	// the top 20 bits.
	uassert.Equal(t, uint64(0xDEADB000), uint64(immU(lui(1, 0xDEADB000))))

	// J-type, 21 bits with bit 0 always zero.
	uassert.Equal(t, uint64(0x7FE), uint64(immJ(jal(1, 0x7FE))))
	uassert.Equal(t, uint64(0xFFF00000), uint64(immJ(jal(1, 0x100000))))
	uassert.Equal(t, uint64(0xFFFFFFFE), uint64(immJ(jal(1, 0x1FFFFE))))
}

func jalr(rd, rs1, imm uint32) uint32 { return iType(imm, rs1, 0x0, rd, opJALR) }

package riscv

import "gno.land/p/moul/x/vm/vmkit/v0"

// The syscall table: the entire interface between a guest and the chain.
//
// Register-passing, in the RISC-V Linux convention a compiler already knows:
// a7 (x17) selects the call, a0..a2 (x10..x12) carry arguments, a0 receives the
// result. A guest written against these needs no gno-specific runtime, only the
// three lines of inline assembly every no_std program already has for ecall.
//
// Deliberately small. Every call here maps onto something [vmkit.Host] already
// offers, because the Host is the audited surface and a syscall that reaches
// past it would be a second, unreviewed one.
const (
	sysExit   = 93 // a0 = status. The Linux number, so a guest can reuse its libc shim.
	sysWrite  = 64 // a0 = fd (ignored), a1 = buf, a2 = len -> Host.Output
	sysRead   = 63 // a0 = fd (ignored), a1 = buf, a2 = len <- Host.Input
	sysHeight = 90 // -> block height
	sysNow    = 91 // -> block time, Unix seconds
	sysCaller = 92 // a0 = buf, a1 = len; writes the caller address, returns bytes written
	sysLog    = 94 // a0 = buf, a1 = len -> Host.Log
	sysEmit   = 95 // a0 = type buf, a1 = type len, a2 = body buf, a3 = body len
)

// maxSyscallBytes bounds one call's buffer. A guest asking to write a gigabyte
// is a guest that found the host's allocator, not one with something to say.
const maxSyscallBytes = 64 * 1024

// ecall dispatches a syscall. It returns the machine status and whether the
// machine should stop: only exit stops it, everything else returns to the guest
// with a0 set.
func (m *Machine) ecall(h vmkit.Host) (vmkit.Status, bool) {
	switch m.reg[17] { // a7
	case sysExit:
		// The guest's exit status is not the machine's: a program that returns
		// 1 has halted, it has not trapped. Trapping is for what the machine
		// could not do, and a chain should not confuse "your code said no"
		// with "the VM broke".
		return vmkit.Halted, true

	case sysWrite:
		buf, ok := m.readGuest(m.reg[11], m.reg[12])
		if !ok {
			m.reg[10] = ^uint32(0)
			return vmkit.Running, false
		}
		h.Output(buf)
		m.outLen += len(buf)
		m.reg[10] = uint32(len(buf))

	case sysRead:
		in := h.Input()
		n := int(m.reg[12])
		if n > len(in) {
			n = len(in)
		}
		if n > maxSyscallBytes {
			n = maxSyscallBytes
		}
		if !m.writeGuest(m.reg[11], in[:n]) {
			m.reg[10] = ^uint32(0)
			return vmkit.Running, false
		}
		m.reg[10] = uint32(n)

	case sysHeight:
		m.reg[10] = uint32(h.Height())

	case sysNow:
		m.reg[10] = uint32(h.Now())

	case sysCaller:
		addr := []byte(h.Caller().String())
		n := int(m.reg[11])
		if n > len(addr) {
			n = len(addr)
		}
		if !m.writeGuest(m.reg[10], addr[:n]) {
			m.reg[10] = ^uint32(0)
			return vmkit.Running, false
		}
		m.reg[10] = uint32(n)

	case sysLog:
		buf, ok := m.readGuest(m.reg[10], m.reg[11])
		if !ok {
			m.reg[10] = ^uint32(0)
			return vmkit.Running, false
		}
		h.Log(string(buf))
		m.reg[10] = uint32(len(buf))

	case sysEmit:
		typ, ok1 := m.readGuest(m.reg[10], m.reg[11])
		body, ok2 := m.readGuest(m.reg[12], m.reg[13])
		if !ok1 || !ok2 {
			m.reg[10] = ^uint32(0)
			return vmkit.Running, false
		}
		h.Emit(string(typ), "body", string(body))
		m.reg[10] = 0

	default:
		// An unknown syscall is a trap, not a silent zero. A guest compiled
		// against a newer table must fail loudly on an older host rather than
		// read a success it did not get.
		m.trap = "unknown syscall"
		return vmkit.Trapped, true
	}
	return vmkit.Running, false
}

// readGuest copies a buffer out of guest memory, refusing anything out of range
// or larger than maxSyscallBytes.
func (m *Machine) readGuest(addr, length uint32) ([]byte, bool) {
	if length > maxSyscallBytes || !m.mem.inRange(addr, int(length)) {
		return nil, false
	}
	out := make([]byte, length)
	copy(out, m.mem.b[addr:addr+length])
	return out, true
}

// writeGuest copies into guest memory, marking the pages it touched.
func (m *Machine) writeGuest(addr uint32, b []byte) bool {
	if len(b) > maxSyscallBytes || !m.mem.inRange(addr, len(b)) {
		return false
	}
	copy(m.mem.b[addr:], b)
	for i := 0; i < len(b); i++ {
		m.mem.dirty[(uint64(addr)+uint64(i))/PageSize] = true
	}
	return true
}

// Package riscv is an RV32IM emulator for gno.land: 48 instructions that every
// real compiler already targets.
//
// A guest here is not written in a new language. `rustc --target
// riscv32im-unknown-none-elf`, `clang -target riscv32`, TinyGo and Zig all emit
// it, so a program arrives compiled by the real compiler and optimized by the
// real optimizer. The interpreter is a decode loop rather than a semantic
// minefield: fetch four bytes, switch on seven bits, do arithmetic.
//
// No F or D. No floats means no rounding-mode ambiguity and nothing that can
// differ between nodes. The M extension's divide-by-zero and overflow cases are
// defined by the spec to RETURN a value rather than trap, which is exactly what
// a deterministic chain wants.
//
// It implements [vmkit.Machine], so it shares the fuel meter, the snapshot
// codec and the instance store with [p/moul/x/vm/bf](/p/moul/x/vm/bf/v0). That
// sharing is the point: the second guest is what tells you whether the ABI was
// shaped around the first one.
//
// Live demo: [r/moul/x/vm/riscvdemo](/r/moul/x/vm/riscvdemo/v0).
package riscv

import (
	"errors"

	"gno.land/p/moul/x/vm/vmkit/v0"
)

// VMName is the identifier this machine registers under in a vmkit.Instance.
const VMName = "riscv32im"

// DefaultEntry is where a flat text image is conventionally loaded and where
// execution starts. Low enough to leave a scratch page below it, aligned, and
// nothing about the machine requires it: NewMachine takes the entry point.
const DefaultEntry uint32 = 0x1000

const (
	snapMagic uint32 = 0x52563332 // "RV32"

	// snapVersion 2 carries the text segment's extent, which version 1 did
	// not need because the interpreter decoded from memory on every fetch.
	// Predecoding moved that work to load time, so a restored hart has to be
	// told which part of its memory is code.
	snapVersion byte = 2
)

// ErrNoProgram is returned when a Machine is stepped with no image loaded.
var ErrNoProgram = errors.New("riscv: machine has no program")

// Machine is an RV32IM hart, mid-execution.
type Machine struct {
	reg [32]uint32
	pc  uint32
	mem *Memory

	// code is the text segment with its fields already pulled apart. See
	// predecode.gno for why the dispatch loop reads arrays and not memory.
	code *code

	status vmkit.Status
	trap   string

	// out is what the guest wrote through the write syscall, mirrored to the
	// host as it goes. Kept here too so a snapshot round-trips it.
	outLen int
}

// NewMachine returns a hart with the image loaded at entry, pc at entry, and
// the stack pointer at the top of memory.
func NewMachine(image []byte, entry uint32) (*Machine, error) {
	if entry%4 != 0 {
		return nil, errors.New("riscv: entry point is not 4-byte aligned")
	}
	if len(image)%4 != 0 {
		return nil, errors.New("riscv: image length is not a whole number of instructions")
	}
	m := &Machine{mem: NewMemory(), pc: entry, status: vmkit.Running}
	if !m.mem.WriteImage(entry, image) {
		return nil, errors.New("riscv: image does not fit at the entry point")
	}
	m.code = predecode(entry, image)
	// x2 is sp by convention. A guest that never touches the stack does not
	// care; one compiled by rustc does, immediately.
	m.reg[2] = MemSize
	return m, nil
}

// LoadData places initialized data in memory, outside the text segment.
//
// The other half of a flat-image loader. A program with a .data section needs
// its initial bytes in memory and needs to write them back afterwards, which
// the text segment forbids: W xor X is what makes the predecode sound. So the
// linker puts data at its own address and it arrives here separately, rather
// than being concatenated onto the code and silently becoming read-only.
//
// The pages are marked dirty, so a snapshot carries the data the same way it
// carries the program.
func (m *Machine) LoadData(addr uint32, b []byte) error {
	if m.mem == nil {
		return ErrNoProgram
	}
	if len(b) > 0 && m.code != nil && m.code.words > 0 {
		lo, hi := uint64(addr), uint64(addr)+uint64(len(b))
		if lo < uint64(m.code.end) && hi > uint64(m.code.base) {
			return errors.New("riscv: data segment overlaps the text segment")
		}
	}
	if !m.mem.WriteImage(addr, b) {
		return errors.New("riscv: data does not fit at that address")
	}
	return nil
}

// Registers returns a copy of the register file, for tests and rendering.
func (m *Machine) Registers() [32]uint32 { return m.reg }

// PC returns the program counter.
func (m *Machine) PC() uint32 { return m.pc }

// Memory returns the address space.
func (m *Machine) Memory() *Memory { return m.mem }

// Status returns the machine's status.
func (m *Machine) Status() vmkit.Status { return m.status }

// Trap returns why the machine trapped, making Machine a [vmkit.Trapper].
func (m *Machine) Trap() string { return m.trap }

// Step runs until the program halts, traps, or spends `fuel` instructions.
//
// Written the way the bf ladder concluded, and for the same measured reasons:
// the hot state is in locals and written back once, and the fuel counter is two
// locals rather than a vmkit.Meter, because calling a method per instruction
// cost 86% there and would cost more here, where an instruction is cheaper.
//
// Two things in this loop look like premature optimization and are not, both
// measured in switchcost_test.gno on this VM:
//
//   - The case order is the internal opcode order from predecode.gno, which is
//     by dynamic frequency, because the GnoVM scans switch cases in source
//     order at 278 gas each. Reordering the arms below changes what the
//     interpreter costs.
//   - Everything the loop touches is a local. Reading cop[i] through m.code.op
//     instead would pay for two field lookups on every instruction.
func (m *Machine) Step(h vmkit.Host, fuel int64) (int64, vmkit.Status) {
	if m.mem == nil || m.code == nil {
		m.status, m.trap = vmkit.Trapped, "no program"
		return 0, m.status
	}
	if m.status != vmkit.Running {
		return 0, m.status
	}

	pc := m.pc
	// A misaligned pc would index the word containing it rather than trap,
	// because the index is a shift. Only a restored snapshot can get here with
	// one, since JALR is the only instruction that can produce it and it
	// checks its own target.
	if pc%4 != 0 {
		m.status, m.trap = vmkit.Trapped, "misaligned program counter"
		return 0, m.status
	}

	reg := &m.reg
	mem := m.mem

	c := m.code
	cop, crd, crs1, crs2, cimm := c.op, c.rd, c.rs1, c.rs2, c.imm
	cbase, cwords, cend := c.base, c.words, c.end
	defer func() { m.pc = pc }()

	budget := fuel
	if budget < 0 {
		budget = vmkit.Unmetered
	}
	metered := budget != vmkit.Unmetered
	var used int64

	for {
		if metered && used >= budget {
			return used, vmkit.Running
		}
		used++

		// One subtraction and one shift replace the fetch. A pc below the text
		// segment underflows to a huge index and is caught by the same
		// comparison, which is why there is no second bound here.
		i := (pc - cbase) >> 2
		if i >= cwords {
			m.status, m.trap = vmkit.Trapped, "instruction fetch out of range"
			return used, m.status
		}
		next := pc + 4

		switch cop[i] {
		case iADDI:
			reg[crd[i]] = reg[crs1[i]] + cimm[i]
		case iLW:
			v, ok := mem.Load32(reg[crs1[i]] + cimm[i])
			if !ok {
				m.status, m.trap = vmkit.Trapped, "load out of range"
				return used, m.status
			}
			reg[crd[i]] = v
		case iSW:
			addr := reg[crs1[i]] + cimm[i]
			if addr < cend && addr+4 > cbase {
				m.status, m.trap = vmkit.Trapped, "store into text segment"
				return used, m.status
			}
			if !mem.Store32(addr, reg[crs2[i]]) {
				m.status, m.trap = vmkit.Trapped, "store out of range"
				return used, m.status
			}
		case iADD:
			reg[crd[i]] = reg[crs1[i]] + reg[crs2[i]]
		case iBNE:
			if reg[crs1[i]] != reg[crs2[i]] {
				next = pc + cimm[i]
			}
		case iBEQ:
			if reg[crs1[i]] == reg[crs2[i]] {
				next = pc + cimm[i]
			}
		case iJAL:
			reg[crd[i]] = next
			next = pc + cimm[i]
		case iJALR:
			// The target is computed before rd is written, because rd and rs1
			// are allowed to be the same register and usually are: `ret` is
			// jalr x0, 0(x1).
			t := (reg[crs1[i]] + cimm[i]) &^ 1
			if t%4 != 0 {
				m.status, m.trap = vmkit.Trapped, "misaligned jump target"
				return used, m.status
			}
			reg[crd[i]] = next
			next = t
		case iLUI:
			reg[crd[i]] = cimm[i]
		case iSLLI:
			reg[crd[i]] = reg[crs1[i]] << (cimm[i] & 0x1F)
		case iSRLI:
			reg[crd[i]] = reg[crs1[i]] >> (cimm[i] & 0x1F)
		case iANDI:
			reg[crd[i]] = reg[crs1[i]] & cimm[i]
		case iSUB:
			reg[crd[i]] = reg[crs1[i]] - reg[crs2[i]]
		case iORI:
			reg[crd[i]] = reg[crs1[i]] | cimm[i]
		case iXORI:
			reg[crd[i]] = reg[crs1[i]] ^ cimm[i]
		case iBLT:
			if int32(reg[crs1[i]]) < int32(reg[crs2[i]]) {
				next = pc + cimm[i]
			}
		case iBGE:
			if int32(reg[crs1[i]]) >= int32(reg[crs2[i]]) {
				next = pc + cimm[i]
			}
		case iBLTU:
			if reg[crs1[i]] < reg[crs2[i]] {
				next = pc + cimm[i]
			}
		case iBGEU:
			if reg[crs1[i]] >= reg[crs2[i]] {
				next = pc + cimm[i]
			}
		case iSRAI:
			reg[crd[i]] = uint32(int32(reg[crs1[i]]) >> (cimm[i] & 0x1F))
		case iSLL:
			reg[crd[i]] = reg[crs1[i]] << (reg[crs2[i]] & 0x1F)
		case iSRL:
			reg[crd[i]] = reg[crs1[i]] >> (reg[crs2[i]] & 0x1F)
		case iSRA:
			reg[crd[i]] = uint32(int32(reg[crs1[i]]) >> (reg[crs2[i]] & 0x1F))
		case iAND:
			reg[crd[i]] = reg[crs1[i]] & reg[crs2[i]]
		case iOR:
			reg[crd[i]] = reg[crs1[i]] | reg[crs2[i]]
		case iXOR:
			reg[crd[i]] = reg[crs1[i]] ^ reg[crs2[i]]
		case iLBU:
			v, ok := mem.Load8(reg[crs1[i]] + cimm[i])
			if !ok {
				m.status, m.trap = vmkit.Trapped, "load out of range"
				return used, m.status
			}
			reg[crd[i]] = uint32(v)
		case iLB:
			v, ok := mem.Load8(reg[crs1[i]] + cimm[i])
			if !ok {
				m.status, m.trap = vmkit.Trapped, "load out of range"
				return used, m.status
			}
			reg[crd[i]] = uint32(int32(int8(v)))
		case iLH:
			v, ok := mem.Load16(reg[crs1[i]] + cimm[i])
			if !ok {
				m.status, m.trap = vmkit.Trapped, "load out of range"
				return used, m.status
			}
			reg[crd[i]] = uint32(int32(int16(v)))
		case iLHU:
			v, ok := mem.Load16(reg[crs1[i]] + cimm[i])
			if !ok {
				m.status, m.trap = vmkit.Trapped, "load out of range"
				return used, m.status
			}
			reg[crd[i]] = uint32(v)
		case iSB:
			addr := reg[crs1[i]] + cimm[i]
			if addr < cend && addr+4 > cbase {
				m.status, m.trap = vmkit.Trapped, "store into text segment"
				return used, m.status
			}
			if !mem.Store8(addr, uint8(reg[crs2[i]])) {
				m.status, m.trap = vmkit.Trapped, "store out of range"
				return used, m.status
			}
		case iSH:
			addr := reg[crs1[i]] + cimm[i]
			if addr < cend && addr+4 > cbase {
				m.status, m.trap = vmkit.Trapped, "store into text segment"
				return used, m.status
			}
			if !mem.Store16(addr, uint16(reg[crs2[i]])) {
				m.status, m.trap = vmkit.Trapped, "store out of range"
				return used, m.status
			}
		case iAUIPC:
			reg[crd[i]] = pc + cimm[i]
		case iSLT:
			reg[crd[i]] = b2u(int32(reg[crs1[i]]) < int32(reg[crs2[i]]))
		case iSLTU:
			reg[crd[i]] = b2u(reg[crs1[i]] < reg[crs2[i]])
		case iSLTI:
			reg[crd[i]] = b2u(int32(reg[crs1[i]]) < int32(cimm[i]))
		case iSLTIU:
			reg[crd[i]] = b2u(reg[crs1[i]] < cimm[i])
		case iMUL:
			reg[crd[i]] = reg[crs1[i]] * reg[crs2[i]]
		case iMULH:
			reg[crd[i]] = uint32((int64(int32(reg[crs1[i]])) * int64(int32(reg[crs2[i]]))) >> 32)
		case iMULHSU:
			reg[crd[i]] = uint32((int64(int32(reg[crs1[i]])) * int64(uint64(reg[crs2[i]]))) >> 32)
		case iMULHU:
			reg[crd[i]] = uint32((uint64(reg[crs1[i]]) * uint64(reg[crs2[i]])) >> 32)
		case iDIV:
			// The M extension defines divide by zero and the one signed
			// overflow case to RETURN a value rather than trap. That is what
			// makes it safe on a chain: there is no host arithmetic exception
			// to differ between nodes.
			reg[crd[i]] = divS(int32(reg[crs1[i]]), int32(reg[crs2[i]]))
		case iDIVU:
			if reg[crs2[i]] == 0 {
				reg[crd[i]] = ^uint32(0)
			} else {
				reg[crd[i]] = reg[crs1[i]] / reg[crs2[i]]
			}
		case iREM:
			reg[crd[i]] = remS(int32(reg[crs1[i]]), int32(reg[crs2[i]]))
		case iREMU:
			if reg[crs2[i]] == 0 {
				reg[crd[i]] = reg[crs1[i]]
			} else {
				reg[crd[i]] = reg[crs1[i]] % reg[crs2[i]]
			}
		case iECALL:
			st, halt := m.ecall(h)
			if halt {
				// pc advances past the ecall before returning, so a halted
				// hart points at what it would run next rather than at the
				// syscall it already made. The deferred write-back is the only
				// thing that sets m.pc, so assigning the local is how this is
				// said.
				m.status = st
				pc = next
				return used, m.status
			}
		case iEBREAK:
			m.status, m.trap = vmkit.Trapped, "ebreak"
			pc = next
			return used, m.status
		case iFENCE:
			// FENCE orders memory for a hart that has neighbours. There is
			// exactly one here, so it is architecturally a no-op rather than
			// an unimplemented instruction.
		default:
			m.status, m.trap = vmkit.Trapped, "illegal instruction"
			return used, m.status
		}

		// x0 is hardwired to zero. Writing it is legal and discarded, and
		// clearing after the fact is cheaper than branching on rd in every
		// arm above.
		reg[0] = 0
		pc = next
	}
}

// b2u is the spec's "set if" result: 1 or 0, never a Go bool.
func b2u(b bool) uint32 {
	if b {
		return 1
	}
	return 0
}

// divS is DIV with the two cases the spec pins down: division by zero yields
// all ones, and the most negative value divided by -1 overflows to itself.
func divS(a, b int32) uint32 {
	if b == 0 {
		return ^uint32(0)
	}
	if a == -2147483648 && b == -1 {
		return uint32(a)
	}
	return uint32(a / b)
}

// remS is REM, with the matching pair: remainder by zero is the dividend, and
// the overflow case is zero.
func remS(a, b int32) uint32 {
	if b == 0 {
		return uint32(a)
	}
	if a == -2147483648 && b == -1 {
		return 0
	}
	return uint32(a % b)
}

package riscv

import "gno.land/p/moul/x/vm/vmkit/v0"

// Memory is the guest's flat address space, with a snapshot that carries only
// the pages it actually touched.
//
// The shape is the one the bf ladder argued for. Running memory is a flat
// []byte because a load or a store happens on a large fraction of instructions
// and an avl lookup per access would dominate the interpreter the way
// vmkit.Meter.Charge did there. Snapshot cost is solved separately, by a dirty
// bitmap: a program that writes one page pauses in one page, not in a megabyte,
// which is the same trick that lets a bf hello world pause in 43 bytes.
//
// That answers the open question on the design issue ("memory size versus
// snapshot cost") without paying for it on every instruction.
const (
	// PageSize is the snapshot granularity, not an MMU page: there is no
	// address translation here, only bookkeeping about what changed.
	PageSize = 4096

	// MemSize is the address space. 1 MiB is far more than a no_std guest
	// needs and small enough that the flat allocation is not the cost.
	MemSize = 1 << 20

	pageCount = MemSize / PageSize
)

// Memory is a flat address space plus the record of which pages were written.
type Memory struct {
	b     []byte
	dirty []bool
}

// NewMemory returns a zeroed address space.
func NewMemory() *Memory {
	return &Memory{b: make([]byte, MemSize), dirty: make([]bool, pageCount)}
}

// Size returns the address space size.
func (m *Memory) Size() int { return len(m.b) }

// DirtyPages reports how many pages the guest has written, which is what a
// snapshot costs.
func (m *Memory) DirtyPages() int {
	n := 0
	for _, d := range m.dirty {
		if d {
			n++
		}
	}
	return n
}

// inRange reports whether [addr, addr+size) is inside the address space.
//
// Out of range is a trap rather than a wrap. RISC-V leaves the behaviour of an
// access outside physical memory to the platform, and a chain has to pick the
// one that cannot differ between nodes: refusing is deterministic, wrapping
// invites a guest to alias two addresses and get different answers from
// different memory sizes.
func (m *Memory) inRange(addr uint32, size int) bool {
	end := uint64(addr) + uint64(size)
	return end <= uint64(len(m.b))
}

// Load8, Load16 and Load32 read little-endian, which is what RV32 is.
func (m *Memory) Load8(addr uint32) (uint8, bool) {
	if !m.inRange(addr, 1) {
		return 0, false
	}
	return m.b[addr], true
}

func (m *Memory) Load16(addr uint32) (uint16, bool) {
	if !m.inRange(addr, 2) {
		return 0, false
	}
	return uint16(m.b[addr]) | uint16(m.b[addr+1])<<8, true
}

func (m *Memory) Load32(addr uint32) (uint32, bool) {
	if !m.inRange(addr, 4) {
		return 0, false
	}
	return uint32(m.b[addr]) | uint32(m.b[addr+1])<<8 |
		uint32(m.b[addr+2])<<16 | uint32(m.b[addr+3])<<24, true
}

func (m *Memory) Store8(addr uint32, v uint8) bool {
	if !m.inRange(addr, 1) {
		return false
	}
	m.b[addr] = v
	m.dirty[addr/PageSize] = true
	return true
}

func (m *Memory) Store16(addr uint32, v uint16) bool {
	if !m.inRange(addr, 2) {
		return false
	}
	m.b[addr] = uint8(v)
	m.b[addr+1] = uint8(v >> 8)
	m.dirty[addr/PageSize] = true
	m.dirty[(addr+1)/PageSize] = true
	return true
}

func (m *Memory) Store32(addr uint32, v uint32) bool {
	if !m.inRange(addr, 4) {
		return false
	}
	m.b[addr] = uint8(v)
	m.b[addr+1] = uint8(v >> 8)
	m.b[addr+2] = uint8(v >> 16)
	m.b[addr+3] = uint8(v >> 24)
	m.dirty[addr/PageSize] = true
	m.dirty[(addr+3)/PageSize] = true
	return true
}

// WriteImage places a program image at addr and marks the pages it covers, so
// a snapshot taken before the first store still carries the program.
func (m *Memory) WriteImage(addr uint32, img []byte) bool {
	if !m.inRange(addr, len(img)) {
		return false
	}
	copy(m.b[addr:], img)
	for i := 0; i < len(img); i++ {
		m.dirty[(uint64(addr)+uint64(i))/PageSize] = true
	}
	return true
}

// Snapshot writes only the dirty pages, each prefixed by its index.
func (m *Memory) Snapshot(w *vmkit.Writer) {
	w.Uint32(uint32(m.DirtyPages()))
	for i, d := range m.dirty {
		if !d {
			continue
		}
		w.Uint32(uint32(i))
		w.Bytes(m.b[i*PageSize : (i+1)*PageSize])
	}
}

// Restore reads a snapshot written by Snapshot into a zeroed address space.
func (m *Memory) Restore(r *vmkit.Reader) error {
	m.b = make([]byte, MemSize)
	m.dirty = make([]bool, pageCount)
	n := int(r.Uint32())
	if n < 0 || n > pageCount {
		return vmkit.ErrBadSnapshot
	}
	for i := 0; i < n; i++ {
		idx := int(r.Uint32())
		page := r.Bytes()
		if err := r.Err(); err != nil {
			return err
		}
		if idx < 0 || idx >= pageCount || len(page) != PageSize {
			return vmkit.ErrBadSnapshot
		}
		copy(m.b[idx*PageSize:], page)
		m.dirty[idx] = true
	}
	return r.Err()
}

package riscv

// Predecode: the image is turned into fields once, at load, and the dispatch
// loop only indexes arrays.
//
// Two measurements forced this shape, both in switchcost_test.gno:
//
//   - The GnoVM scans switch cases in source order. Reaching case 47 of a
//     48-case switch costs 13,358 gas against 292 for case 0, a measured 278
//     gas per case skipped. So the internal opcodes below are ordered by how
//     often compiled code actually executes them, and that ordering is a
//     performance decision, not a stylistic one. Do not sort this list.
//   - An elementary operation costs on the order of 280 gas. Fetching four
//     bytes and reassembling them is fourteen of those, on every instruction,
//     forever. Doing it once per word instead is the single largest saving
//     available to an interpreter here.
//
// The decoders in decode.gno are used verbatim below rather than inlined,
// because predecode runs once per word in the image and not once per executed
// instruction. That is the point: the expensive, readable code moved off the
// hot path instead of being duplicated onto it.

// Internal opcodes, ordered by expected dynamic frequency in compiled code.
// The first dozen are what a loop nest and a function prologue are made of.
const (
	iADDI uint8 = iota
	iLW
	iSW
	iADD
	iBNE
	iBEQ
	iJAL
	iJALR
	iLUI
	iSLLI
	iSRLI
	iANDI
	iSUB
	iORI
	iXORI
	iBLT
	iBGE
	iBLTU
	iBGEU
	iSRAI
	iSLL
	iSRL
	iSRA
	iAND
	iOR
	iXOR
	iLBU
	iLB
	iLH
	iLHU
	iSB
	iSH
	iAUIPC
	iSLT
	iSLTU
	iSLTI
	iSLTIU
	iMUL
	iMULH
	iMULHSU
	iMULHU
	iDIV
	iDIVU
	iREM
	iREMU
	iECALL
	iEBREAK
	iFENCE
	iILLEGAL
)

// code is an image with its fields already pulled apart. Parallel arrays, not
// a slice of structs: an arm reads three or four fields, and paying for the
// ones it does not read is the cost this whole file exists to avoid.
type code struct {
	base  uint32 // the address word 0 sits at
	words uint32 // how many instructions the text segment holds
	end   uint32 // base + 4*words, the first address past the text
	op    []uint8
	rd    []uint8
	rs1   []uint8
	rs2   []uint8
	imm   []uint32
}

// predecode walks an image and records, for every word, what it is and what
// its operands are. A word that is not an instruction becomes iILLEGAL and
// traps only if it is ever executed, which is what keeps a constant pool in
// the middle of a text segment legal.
func predecode(base uint32, img []byte) *code {
	n := uint32(len(img) / 4)
	c := &code{
		base:  base,
		words: n,
		end:   base + n*4,
		op:    make([]uint8, n),
		rd:    make([]uint8, n),
		rs1:   make([]uint8, n),
		rs2:   make([]uint8, n),
		imm:   make([]uint32, n),
	}
	for i := uint32(0); i < n; i++ {
		j := i * 4
		inst := uint32(img[j]) | uint32(img[j+1])<<8 |
			uint32(img[j+2])<<16 | uint32(img[j+3])<<24
		op, imm := decodeWord(inst)
		c.op[i] = op
		c.imm[i] = imm
		// The three register selectors are in the same place in every format
		// that has them, and are harmless in the formats that do not, so they
		// are taken unconditionally and spelled out: this loop already costs
		// more than executing the instruction does.
		c.rd[i] = uint8((inst >> 7) & 0x1F)
		c.rs1[i] = uint8((inst >> 15) & 0x1F)
		c.rs2[i] = uint8((inst >> 20) & 0x1F)
	}
	return c
}

// decodeWord returns both the internal opcode and the immediate, in one pass.
//
// They were two functions once, and splitting them cost 22 case labels: the
// second switch had to ask all over again which format the instruction was, and
// the GnoVM scans case labels one at a time. Deciding both in the arm that
// already knows the answer took predecode from 31.4k gas per word to 19.6k.
//
// The immediate decoders are still called rather than inlined. This runs once
// per word in the image, not once per executed instruction, and sign extension
// is the subtle part of RV32 decoding: it belongs in one place, spelled out,
// with decode_test.gno round-tripping it against the assembler.
func decodeWord(inst uint32) (uint8, uint32) {
	f3 := funct3(inst)
	switch opcode(inst) {
	case opImm:
		imm := immI(inst)
		switch f3 {
		case 0x0:
			return iADDI, imm
		case 0x1:
			return iSLLI, imm
		case 0x2:
			return iSLTI, imm
		case 0x3:
			return iSLTIU, imm
		case 0x4:
			return iXORI, imm
		case 0x5:
			if funct7(inst) == 0x20 {
				return iSRAI, imm
			}
			return iSRLI, imm
		case 0x6:
			return iORI, imm
		case 0x7:
			return iANDI, imm
		}
	case opLoad:
		imm := immI(inst)
		switch f3 {
		case 0x0:
			return iLB, imm
		case 0x1:
			return iLH, imm
		case 0x2:
			return iLW, imm
		case 0x4:
			return iLBU, imm
		case 0x5:
			return iLHU, imm
		}
	case opStore:
		imm := immS(inst)
		switch f3 {
		case 0x0:
			return iSB, imm
		case 0x1:
			return iSH, imm
		case 0x2:
			return iSW, imm
		}
	case opReg:
		f7 := funct7(inst)
		if f7 == 0x01 {
			switch f3 {
			case 0x0:
				return iMUL, 0
			case 0x1:
				return iMULH, 0
			case 0x2:
				return iMULHSU, 0
			case 0x3:
				return iMULHU, 0
			case 0x4:
				return iDIV, 0
			case 0x5:
				return iDIVU, 0
			case 0x6:
				return iREM, 0
			case 0x7:
				return iREMU, 0
			}
		}
		switch f3 {
		case 0x0:
			if f7 == 0x20 {
				return iSUB, 0
			}
			return iADD, 0
		case 0x1:
			return iSLL, 0
		case 0x2:
			return iSLT, 0
		case 0x3:
			return iSLTU, 0
		case 0x4:
			return iXOR, 0
		case 0x5:
			if f7 == 0x20 {
				return iSRA, 0
			}
			return iSRL, 0
		case 0x6:
			return iOR, 0
		case 0x7:
			return iAND, 0
		}
	case opBranch:
		imm := immB(inst)
		switch f3 {
		case 0x0:
			return iBEQ, imm
		case 0x1:
			return iBNE, imm
		case 0x4:
			return iBLT, imm
		case 0x5:
			return iBGE, imm
		case 0x6:
			return iBLTU, imm
		case 0x7:
			return iBGEU, imm
		}
	case opLUI:
		return iLUI, immU(inst)
	case opAUIPC:
		return iAUIPC, immU(inst)
	case opJAL:
		return iJAL, immJ(inst)
	case opJALR:
		if f3 == 0x0 {
			return iJALR, immI(inst)
		}
	case opFence:
		return iFENCE, 0
	case opSystem:
		if immI(inst) == 0 {
			return iECALL, 0
		}
		return iEBREAK, 0
	}
	return iILLEGAL, 0
}

package riscv

import (
	"testing"

	"gno.land/p/moul/x/vm/vmkit/v0"
	"gno.land/p/nt/uassert/v0"
)

// classify collapses the spec's opcode / funct3 / funct7 tree onto one byte,
// and every arm of the dispatch loop trusts it. These are the pairs that share
// a funct3 and differ only in funct7, which is where a collapse goes wrong.
func TestClassifySeparatesTheAmbiguousPairs(t *testing.T) {
	cases := []struct {
		inst uint32
		want uint8
	}{
		{add(1, 2, 3), iADD},
		{sub(1, 2, 3), iSUB},
		{mul(1, 2, 3), iMUL},
		{divi(1, 2, 3), iDIV},
		{remi(1, 2, 3), iREM},
		{addi(1, 2, 5), iADDI},
		{lw(1, 2, 0), iLW},
		{lbu(1, 2, 0), iLBU},
		{sw(1, 2, 0), iSW},
		{bne(1, 2, 4), iBNE},
		{lui(1, 0x1000), iLUI},
		{jal(1, 4), iJAL},
		{ecall(), iECALL},
		{0, iILLEGAL},
	}
	for _, c := range cases {
		op, _ := decodeWord(c.inst)
		uassert.Equal(t, uint64(c.want), uint64(op))
	}
}

// A restored hart has to predecode again, because the arrays are not in the
// snapshot: only the memory pages are. Restoring into a machine that has never
// seen the image is the path a realm actually takes between transactions, and
// it is the one the existing slice test did not cover, because it always
// restored into a machine NewMachine had already loaded.
func TestRestoreIntoABareMachine(t *testing.T) {
	prog := append([]uint32{
		addi(5, 0, 0),
		addi(6, 0, 10),
		add(5, 5, 6),
		addi(6, 6, 0xFFF), // -1
		bne(6, 0, 0x1FF8), // -8
	}, exitWith()...)
	image := asm(prog)

	one, err := NewMachine(image, entry)
	uassert.NoError(t, err)
	one.Step(vmkit.NewTestHost(), vmkit.Unmetered)

	part, err := NewMachine(image, entry)
	uassert.NoError(t, err)
	_, status := part.Step(vmkit.NewTestHost(), 7)
	uassert.Equal(t, "running", status.String())

	var bare Machine
	uassert.NoError(t, bare.Restore(part.Snapshot()))
	_, status = bare.Step(vmkit.NewTestHost(), vmkit.Unmetered)
	uassert.Equal(t, "halted", status.String())
	uassert.Equal(t, uint64(one.Registers()[5]), uint64(bare.Registers()[5]))
	uassert.Equal(t, uint64(55), uint64(bare.Registers()[5]))
}

// Predecoding is only sound if the text cannot change under it, so a store
// into the text segment is a trap rather than a silent disagreement between
// the arrays and the memory. That is W xor X, which is what an ELF text
// segment is anyway, and it removes self-modifying code from the VM entirely.
func TestStoreIntoTextTraps(t *testing.T) {
	prog := append(li(5, entry), addi(6, 0, 1), sw(6, 5, 0))
	prog = append(prog, exitWith()...)
	m, err := NewMachine(asm(prog), entry)
	uassert.NoError(t, err)
	_, status := m.Step(vmkit.NewTestHost(), vmkit.Unmetered)
	uassert.Equal(t, "trapped", status.String())
	uassert.Equal(t, "store into text segment", m.Trap())
}

// A store just below the text segment is legal, or the trap above would be
// catching the wrong thing.
func TestStoreBelowTextIsFine(t *testing.T) {
	prog := append(li(5, entry-4), addi(6, 0, 7), sw(6, 5, 0))
	prog = append(prog, exitWith()...)
	m, err := NewMachine(asm(prog), entry)
	uassert.NoError(t, err)
	_, status := m.Step(vmkit.NewTestHost(), vmkit.Unmetered)
	uassert.Equal(t, "halted", status.String())
	v, ok := m.Memory().Load32(entry - 4)
	uassert.True(t, ok)
	uassert.Equal(t, uint64(7), uint64(v))
}

// A halted hart points past the ecall it halted on, not at it. The deferred
// write-back is the only thing that sets m.pc, so an arm that assigned m.pc
// directly had its assignment silently undone on the way out.
func TestHaltedPCIsPastTheEcall(t *testing.T) {
	m, err := NewMachine(asm(exitWith()), entry)
	uassert.NoError(t, err)
	_, status := m.Step(vmkit.NewTestHost(), vmkit.Unmetered)
	uassert.Equal(t, "halted", status.String())
	// entry: addi a7, x0, 93 -- entry+4: ecall -- so the next pc is entry+8.
	uassert.Equal(t, uint64(entry+8), uint64(m.PC()))
}

// An entry point or an image that is not a whole number of instructions has no
// predecode, so it is refused at load rather than half-executed.
func TestNewMachineRefusesMisalignedImages(t *testing.T) {
	_, err := NewMachine(asm(exitWith()), entry+1)
	uassert.Error(t, err)
	_, err = NewMachine([]byte{1, 2, 3}, entry)
	uassert.Error(t, err)
}

// The index into the predecoded arrays is a shift, so a pc that is not
// 4-aligned would silently execute the word containing it. Only a snapshot can
// deliver one, because JALR checks its own target, so the guard is at entry to
// the loop rather than inside it.
func TestMisalignedPCTraps(t *testing.T) {
	m, err := NewMachine(asm(exitWith()), entry)
	uassert.NoError(t, err)
	m.pc = entry + 2
	_, status := m.Step(vmkit.NewTestHost(), vmkit.Unmetered)
	uassert.Equal(t, "trapped", status.String())
	uassert.Equal(t, "misaligned program counter", m.Trap())
}

// JALR is the only instruction that can compute an odd target, and it clears
// only bit 0, so a target of 2 mod 4 has to be refused where it is made.
func TestJalrRefusesAMisalignedTarget(t *testing.T) {
	prog := append(li(5, entry+6), []uint32{jalr(1, 5, 0)}...)
	prog = append(prog, exitWith()...)
	m, err := NewMachine(asm(prog), entry)
	uassert.NoError(t, err)
	_, status := m.Step(vmkit.NewTestHost(), vmkit.Unmetered)
	uassert.Equal(t, "trapped", status.String())
	uassert.Equal(t, "misaligned jump target", m.Trap())
}

// A .data section has to land somewhere writable, and refusing an overlap with
// the text is the check that keeps a bad linker script from producing a program
// that traps on its first store instead of at load.
func TestLoadDataRefusesTheTextSegment(t *testing.T) {
	m, err := NewMachine(asm(exitWith()), entry)
	uassert.NoError(t, err)

	uassert.Error(t, m.LoadData(entry, []byte{1, 2, 3, 4}))
	uassert.Error(t, m.LoadData(entry-2, []byte{1, 2, 3, 4}))
	uassert.NoError(t, m.LoadData(entry-4, []byte{1, 2, 3, 4}))
	uassert.NoError(t, m.LoadData(0x40000, []byte{9, 8, 7, 6}))
	uassert.Error(t, m.LoadData(MemSize-2, []byte{1, 2, 3, 4}))

	v, ok := m.Memory().Load32(0x40000)
	uassert.True(t, ok)
	uassert.Equal(t, uint64(0x06070809), uint64(v))
}

// Data is memory, so it rides in the snapshot like everything else the guest
// touched. A resumed program must not find its constants gone.
func TestLoadedDataSurvivesASnapshot(t *testing.T) {
	m, err := NewMachine(asm(exitWith()), entry)
	uassert.NoError(t, err)
	uassert.NoError(t, m.LoadData(0x40000, []byte{0xDE, 0xAD, 0xBE, 0xEF}))

	var restored Machine
	uassert.NoError(t, restored.Restore(m.Snapshot()))
	v, ok := restored.Memory().Load32(0x40000)
	uassert.True(t, ok)
	uassert.Equal(t, uint64(0xEFBEADDE), uint64(v))
}

package riscv

import (
	"testing"

	"gno.land/p/moul/x/vm/vmkit/v0"
	"gno.land/p/nt/uassert/v0"
)

// A tiny assembler, so the programs below read as instructions rather than as
// hex. Encoding here and decoding in decode.gno are written from the spec
// independently: if one has a field in the wrong place the tests fail, which is
// the point of not sharing a helper between them.

func rType(f7, rs2, rs1, f3, rd, op uint32) uint32 {
	return f7<<25 | rs2<<20 | rs1<<15 | f3<<12 | rd<<7 | op
}
func iType(imm, rs1, f3, rd, op uint32) uint32 {
	return (imm&0xFFF)<<20 | rs1<<15 | f3<<12 | rd<<7 | op
}
func sType(imm, rs2, rs1, f3, op uint32) uint32 {
	return (imm>>5&0x7F)<<25 | rs2<<20 | rs1<<15 | f3<<12 | (imm&0x1F)<<7 | op
}
func bType(imm, rs2, rs1, f3, op uint32) uint32 {
	return (imm>>12&0x1)<<31 | (imm>>5&0x3F)<<25 | rs2<<20 | rs1<<15 |
		f3<<12 | (imm>>1&0xF)<<8 | (imm>>11&0x1)<<7 | op
}
func uType(imm, rd, op uint32) uint32 { return imm&0xFFFFF000 | rd<<7 | op }
func jType(imm, rd, op uint32) uint32 {
	return (imm>>20&0x1)<<31 | (imm>>1&0x3FF)<<21 | (imm>>11&0x1)<<20 |
		(imm>>12&0xFF)<<12 | rd<<7 | op
}

func addi(rd, rs1, imm uint32) uint32 { return iType(imm, rs1, 0x0, rd, opImm) }
func add(rd, rs1, rs2 uint32) uint32  { return rType(0x00, rs2, rs1, 0x0, rd, opReg) }
func sub(rd, rs1, rs2 uint32) uint32  { return rType(0x20, rs2, rs1, 0x0, rd, opReg) }
func mul(rd, rs1, rs2 uint32) uint32  { return rType(0x01, rs2, rs1, 0x0, rd, opReg) }
func divi(rd, rs1, rs2 uint32) uint32 { return rType(0x01, rs2, rs1, 0x4, rd, opReg) }
func remi(rd, rs1, rs2 uint32) uint32 { return rType(0x01, rs2, rs1, 0x6, rd, opReg) }
func sw(rs2, rs1, imm uint32) uint32  { return sType(imm, rs2, rs1, 0x2, opStore) }
func lw(rd, rs1, imm uint32) uint32   { return iType(imm, rs1, 0x2, rd, opLoad) }
func lbu(rd, rs1, imm uint32) uint32  { return iType(imm, rs1, 0x4, rd, opLoad) }
func bne(rs1, rs2, imm uint32) uint32 { return bType(imm, rs2, rs1, 0x1, opBranch) }
func ecall() uint32                   { return iType(0, 0, 0, 0, opSystem) }

// exitWith is the two instructions every test program ends with: set a7 to the
// exit syscall and trap into the host.
func exitWith() []uint32 { return []uint32{addi(17, 0, sysExit), ecall()} }

func asm(words []uint32) []byte {
	out := make([]byte, 0, len(words)*4)
	for _, w := range words {
		out = append(out, byte(w), byte(w>>8), byte(w>>16), byte(w>>24))
	}
	return out
}

const entry = 0x1000

func run(t *testing.T, words []uint32, h vmkit.Host) *Machine {
	t.Helper()
	m, err := NewMachine(asm(words), entry)
	uassert.NoError(t, err)
	if m == nil {
		return nil
	}
	_, status := m.Step(h, vmkit.Unmetered)
	uassert.Equal(t, "halted", status.String())
	return m
}

func TestArithmetic(t *testing.T) {
	// x5 = 7 + 35; x6 = x5 - 2; x7 = x6 * 3
	prog := append([]uint32{
		addi(5, 0, 7),
		addi(5, 5, 35),
		addi(6, 0, 2),
		sub(6, 5, 6),
		addi(7, 0, 3),
		mul(7, 6, 7),
	}, exitWith()...)
	m := run(t, prog, vmkit.NewTestHost())
	r := m.Registers()
	uassert.Equal(t, uint64(42), uint64(r[5]))
	uassert.Equal(t, uint64(40), uint64(r[6]))
	uassert.Equal(t, uint64(120), uint64(r[7]))
}

// Every immediate in the base set is sign extended from its top bit. Small
// positive programs work either way, which is what makes this the classic
// decoder bug: it only shows up on a negative constant.
func TestImmediatesAreSignExtended(t *testing.T) {
	prog := append([]uint32{
		addi(5, 0, 10),
		addi(5, 5, 0xFFF), // -1
		addi(6, 0, 0x800), // -2048, the most negative 12-bit immediate
	}, exitWith()...)
	m := run(t, prog, vmkit.NewTestHost())
	r := m.Registers()
	uassert.Equal(t, uint64(9), uint64(r[5]))
	uassert.Equal(t, int64(-2048), int64(int32(r[6])))
}

// x0 reads as zero and discards every write, and the spec has no exception.
func TestRegisterZeroIsHardwired(t *testing.T) {
	prog := append([]uint32{
		addi(0, 0, 99),
		add(5, 0, 0),
	}, exitWith()...)
	m := run(t, prog, vmkit.NewTestHost())
	uassert.Equal(t, uint64(0), uint64(m.Registers()[0]))
	uassert.Equal(t, uint64(0), uint64(m.Registers()[5]))
}

func TestLoadsAndStores(t *testing.T) {
	prog := append([]uint32{
		addi(5, 0, 0x7F0), // an address well clear of the program
		addi(6, 0, 0x123),
		sw(6, 5, 0),
		lw(7, 5, 0),
		lbu(8, 5, 0), // little-endian: the low byte is 0x23
	}, exitWith()...)
	m := run(t, prog, vmkit.NewTestHost())
	r := m.Registers()
	uassert.Equal(t, uint64(0x123), uint64(r[7]))
	uassert.Equal(t, uint64(0x23), uint64(r[8]))
}

// A loop, which is the only way to know branches and the pc agree.
func TestBranchLoopSumsToTen(t *testing.T) {
	// x5 = 0; x6 = 5; do { x5 += x6; x6 -= 1 } while (x6 != 0)  => 15
	prog := append([]uint32{
		addi(5, 0, 0),
		addi(6, 0, 5),
		add(5, 5, 6),        // loop:
		addi(6, 6, 0xFFF),   // x6 -= 1
		bne(6, 0, 0x1FF8),   // -8, back to loop
	}, exitWith()...)
	m := run(t, prog, vmkit.NewTestHost())
	uassert.Equal(t, uint64(15), uint64(m.Registers()[5]))
}

// The M extension's defined answers. These are the cases a chain cares about,
// because the spec makes them RETURN rather than trap and every implementation
// therefore has to agree.
func TestDivisionEdgeCases(t *testing.T) {
	const minInt32 = 0x80000000
	prog := append([]uint32{
		addi(5, 0, 7),
		addi(6, 0, 0),
		divi(7, 5, 6), // 7 / 0 = all ones
		remi(8, 5, 6), // 7 % 0 = 7
		uType(minInt32, 9, opLUI),
		addi(10, 0, 0xFFF), // -1
		divi(11, 9, 10),    // overflow: stays minInt32
		remi(12, 9, 10),    // overflow: 0
	}, exitWith()...)
	m := run(t, prog, vmkit.NewTestHost())
	r := m.Registers()
	uassert.Equal(t, uint64(0xFFFFFFFF), uint64(r[7]))
	uassert.Equal(t, uint64(7), uint64(r[8]))
	uassert.Equal(t, uint64(minInt32), uint64(r[11]))
	uassert.Equal(t, uint64(0), uint64(r[12]))
}

// The syscall table is the whole interface between guest and chain.
func TestWriteSyscallReachesTheHost(t *testing.T) {
	// Store "hi" at 0x800, then write(1, 0x800, 2).
	prog := append([]uint32{
		addi(5, 0, 0x7F0),
		addi(6, 0, 'h'),
		sType(0, 6, 5, 0x0, opStore), // sb
		addi(6, 0, 'i'),
		sType(1, 6, 5, 0x0, opStore),
		addi(17, 0, sysWrite),
		addi(10, 0, 1),
		addi(11, 0, 0x7F0),
		addi(12, 0, 2),
		ecall(),
	}, exitWith()...)
	h := vmkit.NewTestHost()
	run(t, prog, h)
	uassert.Equal(t, "hi", h.OutString())
}

// A guest that exits non-zero has HALTED, not trapped: "your code said no" is
// not "the VM broke", and a chain should not conflate them.
func TestNonZeroExitIsStillHalted(t *testing.T) {
	prog := []uint32{addi(10, 0, 1), addi(17, 0, sysExit), ecall()}
	m, err := NewMachine(asm(prog), entry)
	uassert.NoError(t, err)
	_, status := m.Step(vmkit.NewTestHost(), vmkit.Unmetered)
	uassert.Equal(t, "halted", status.String())
	uassert.Equal(t, "", m.Trap())
	uassert.Equal(t, uint64(1), uint64(m.Registers()[10]))
}

func TestUnknownSyscallTraps(t *testing.T) {
	prog := []uint32{addi(17, 0, 777), ecall()}
	m, err := NewMachine(asm(prog), entry)
	uassert.NoError(t, err)
	_, status := m.Step(vmkit.NewTestHost(), vmkit.Unmetered)
	uassert.Equal(t, "trapped", status.String())
	uassert.Equal(t, "unknown syscall", m.Trap())
}

func TestIllegalInstructionTraps(t *testing.T) {
	m, err := NewMachine(asm([]uint32{0xFFFFFFFF}), entry)
	uassert.NoError(t, err)
	_, status := m.Step(vmkit.NewTestHost(), vmkit.Unmetered)
	uassert.Equal(t, "trapped", status.String())
}

func TestFuelStopsTheHart(t *testing.T) {
	prog := append([]uint32{
		addi(5, 0, 1), addi(5, 5, 1), addi(5, 5, 1), addi(5, 5, 1),
	}, exitWith()...)
	m, err := NewMachine(asm(prog), entry)
	uassert.NoError(t, err)
	used, status := m.Step(vmkit.NewTestHost(), 2)
	uassert.Equal(t, int64(2), used)
	uassert.Equal(t, "running", status.String())
	uassert.Equal(t, uint64(2), uint64(m.Registers()[5]))
}

// The property that makes a guest program a contract: slices must equal one go.
func TestSlicedRunEqualsOneShot(t *testing.T) {
	prog := append([]uint32{
		addi(5, 0, 0),
		addi(6, 0, 12),
		add(5, 5, 6),
		addi(6, 6, 0xFFF),
		bne(6, 0, 0x1FF8),
		addi(7, 0, 0x7F0),
		sw(5, 7, 0),
	}, exitWith()...)
	image := asm(prog)

	one, err := NewMachine(image, entry)
	uassert.NoError(t, err)
	one.Step(vmkit.NewTestHost(), vmkit.Unmetered)

	sliced, err := NewMachine(image, entry)
	uassert.NoError(t, err)
	h := vmkit.NewTestHost()
	status := vmkit.Running
	for i := 0; i < 5000 && status == vmkit.Running; i++ {
		fresh, err := NewMachine(image, entry)
		uassert.NoError(t, err)
		uassert.NoError(t, fresh.Restore(sliced.Snapshot()))
		_, status = fresh.Step(h, 3)
		sliced = fresh
	}
	uassert.Equal(t, "halted", status.String())
	uassert.Equal(t, uint64(one.Registers()[5]), uint64(sliced.Registers()[5]))
	uassert.Equal(t, uint64(78), uint64(sliced.Registers()[5]))
}

// A 1 MiB address space must not cost 1 MiB to pause. This is the kill
// criterion vmkit set for continuations, measured rather than asserted.
func TestSnapshotCarriesOnlyTouchedPages(t *testing.T) {
	prog := append([]uint32{
		addi(5, 0, 0x7F0),
		addi(6, 0, 1),
		sw(6, 5, 0),
	}, exitWith()...)
	m := run(t, prog, vmkit.NewTestHost())

	// Two: the page holding the program at 0x1000, and the one holding the
	// store at 0x7F0. Two out of 256, which is the whole point.
	uassert.Equal(t, 2, m.Memory().DirtyPages())
	// The property is proportionality: a snapshot costs what the guest
	// touched plus a fixed header, not what the address space is. Two pages
	// out of 256 means about 8 KiB out of a megabyte.
	snap := m.Snapshot()
	pages := m.Memory().DirtyPages()
	uassert.True(t, len(snap) <= pages*PageSize+512,
		"a snapshot must not exceed its dirty pages plus a header")
	uassert.True(t, len(snap) < MemSize/100,
		"a snapshot of a lightly-used hart must be a rounding error against the address space")
}

func TestRestoreRejectsJunk(t *testing.T) {
	m, err := NewMachine(asm(exitWith()), entry)
	uassert.NoError(t, err)
	uassert.Error(t, m.Restore([]byte{}))
	uassert.Error(t, m.Restore([]byte{1, 2, 3, 4, 5}))

	good := m.Snapshot()
	bad := make([]byte, len(good))
	copy(bad, good)
	bad[4] = 99 // version
	uassert.ErrorIs(t, m.Restore(bad), vmkit.ErrBadSnapshot)
}

// vmkit's plumbing has to work for a second guest, which is the only way to
// know the ABI was not shaped around the first one.
func TestInstanceIntegration(t *testing.T) {
	prog := append([]uint32{addi(5, 0, 21), add(5, 5, 5)}, exitWith()...)
	image := asm(prog)

	inst := vmkit.NewInstance("001", address("g1x"), VMName, image, vmkit.Unmetered)
	h := vmkit.NewTestHost()
	for i := 0; i < 100 && inst.Status == vmkit.Running; i++ {
		m, err := NewMachine(image, entry)
		uassert.NoError(t, err)
		uassert.NoError(t, inst.Run(m, h, 2))
	}
	uassert.Equal(t, "halted", inst.Status.String())
	uassert.True(t, inst.Slices > 1)
}

