// A board that renders every request ever filed is a page that grows without
// bound and a gas cost that grows with it, and this path is permanent. Assert
// the cap holds and that what it hides is counted rather than lost.
func TestRenderCapsEachTable(cur realm, t *testing.T) {
	reset()
	fund(200_000_000)

	const filed = Rows + 5
	for i := 0; i < filed; i++ {
		testing.SetRealm(testing.NewUserRealm(carl))
		Request(cross(cur), zoe.String(), 1_000_000, "batch")
	}
	urequire.Equal(t, int64(filed), Pending())

	page := Render("")
	uassert.Equal(t, Rows, countRows(page), "the open table is capped")
	uassert.True(t, contains(page, "5 more not shown"), "and the rest are counted")

	// Decide them all: the open table empties and the decided one caps in turn,
	// newest first, so the most recent decision is on the page and the oldest
	// is the one hidden.
	for id := int64(1); id <= filed; id++ {
		testing.SetRealm(testing.NewUserRealm(Owner))
		Deny(cross(cur), id, "batch")
	}
	page = Render("")
	uassert.Equal(t, int64(0), Pending())
	uassert.Equal(t, Rows, countRows(page), "the decided table is capped too")
	uassert.True(t, contains(page, "5 more not shown"))
	uassert.True(t, contains(page, ":req/"+strconv.FormatInt(int64(filed), 10)+")"), "newest is shown")
	uassert.False(t, contains(page, ":req/1)"), "oldest is the one hidden")

	testing.SetRealm(testing.NewUserRealm(Owner))
	Withdraw(cross(cur), Balance())
}

// countRows counts request rows on a page: every one links to :req/.
func countRows(page string) int {
	n, needle := 0, "](/r/moul/faucet/v1:req/"
	for i := 0; i+len(needle) <= len(page); i++ {
		if page[i:i+len(needle)] == needle {
			n++
		}
	}
	return n
}

// Path is a hand-written const and the module line is in gnomod.toml, so
// nothing but this test stops them diverging. They must not: Address() derives
// the float from Path, while the banker in Approve spends from cur.Address(),
// which is derived by the VM. A divergence would make Balance() read a
// different account from the one the payout leaves, and the realm would refuse
// payouts it could afford while reporting a float it does not hold.
func TestPathMatchesTheRealmItIsDeployedAs(cur realm, t *testing.T) {
	uassert.Equal(t, cur.Address().String(), Address().String(),
		"Path disagrees with the module line in gnomod.toml")
}

package faucet

import (
	"strconv"
	"strings"

	"gno.land/p/nt/markdown/sanitize/v0"
)

// Rows is how many requests each table on the board shows. The rest are
// counted, not rendered: the per-request page is always reachable by id.
const Rows = 20

// Render shows the float, the open asks and everything already decided.
//
// Two paths: "" is the whole board, "req/<id>" is one request.
//
// Every string on this page that a caller typed goes through sanitize before
// it is concatenated. A reason is arbitrary text from an arbitrary account and
// Render output is markdown that gnoweb parses, so an unescaped one can plant
// a link, an image beacon or gnoweb chrome on a page the realm is signing for.
// This realm's path is permanent, so that bug could only ever be fixed at a
// new path.
func Render(path string) string {
	path = strings.TrimPrefix(path, "/")
	if id, ok := reqPath(path); ok {
		return renderOne(id)
	}
	return renderBoard()
}

func renderBoard() string {
	var b strings.Builder

	b.WriteString("# GNOT faucet\n\n")
	b.WriteString(intro)
	b.WriteString("\n\n")

	b.WriteString("| | |\n| --- | ---: |\n")
	b.WriteString("| Float available | **" + gnot(Balance()) + " GNOT** |\n")
	b.WriteString("| Paid out | " + gnot(totalSent) + " GNOT over " +
		strconv.FormatInt(sentCount, 10) + " request(s) |\n")
	b.WriteString("| Open requests | " + strconv.FormatInt(pendingN, 10) + " |\n")
	b.WriteString("| Refused | " + strconv.FormatInt(deniedCount, 10) + " |\n")
	b.WriteString("| Cap per request | " + gnot(maxPerRequest) + " GNOT |\n")
	b.WriteString("| Float address | `" + Address().String() + "` |\n\n")

	b.WriteString("## Open\n\n")
	b.WriteString(table(true, pendingN))
	b.WriteString("\n## Decided\n\n")
	b.WriteString(table(false, sentCount+deniedCount))

	b.WriteString("\n## Approvers\n\n")
	approvers.Iterate("", "", func(k string, _ any) bool {
		b.WriteString("- `" + k + "`\n")
		return false
	})

	b.WriteString("\n" + howto + "\n")
	return b.String()
}

// table lists at most Rows requests: the open ones oldest first, because a
// queue is worked from the front, and the decided ones newest first, because
// nobody scrolls to the bottom of a ledger.
//
// It takes the total from the realm's counters rather than counting rows, so
// it can STOP iterating once the page is full. A Render that walks every
// request ever filed is a page that grows without bound and a gas cost that
// grows with it, and this realm's path is permanent, so that would only ever
// be fixable at a new path.
func table(open bool, total int64) string {
	if total == 0 {
		return "_Nothing here yet._\n"
	}
	var rows strings.Builder
	shown := int64(0)
	visit := func(_ string, v any) bool {
		r := v.(*request)
		if (r.Status == StatusPending) != open {
			return false
		}
		rows.WriteString("| [" + strconv.FormatInt(r.ID, 10) + "](" + Link + ":req/" +
			strconv.FormatInt(r.ID, 10) + ") | `" + r.To.String() + "` | " +
			gnot(r.Amount) + " | " + sanitize.TableCell(excerpt(r.Reason, 60)) + " | " +
			r.Status + " |\n")
		shown++
		return shown >= Rows // a true return stops the walk
	}
	if open {
		requests.Iterate("", "", visit)
	} else {
		requests.ReverseIterate("", "", visit)
	}

	out := "| # | To | GNOT | Why | State |\n| ---: | --- | ---: | --- | --- |\n" + rows.String()
	if rest := total - shown; rest > 0 {
		out += "\n_" + strconv.FormatInt(rest, 10) + " more not shown._\n"
	}
	return out
}

func renderOne(id int64) string {
	r := find(id)
	if r == nil {
		return "# Request " + strconv.FormatInt(id, 10) + "\n\n_No such request._\n"
	}
	var b strings.Builder
	b.WriteString("# Request " + strconv.FormatInt(r.ID, 10) + "\n\n")
	b.WriteString("| | |\n| --- | --- |\n")
	b.WriteString("| To | `" + r.To.String() + "` |\n")
	b.WriteString("| Amount | " + gnot(r.Amount) + " GNOT |\n")
	b.WriteString("| Filed by | `" + r.By.String() + "` |\n")
	b.WriteString("| Filed at height | " + strconv.FormatInt(r.Asked, 10) + " |\n")
	b.WriteString("| State | " + r.Status + " |\n")
	if r.Status != StatusPending {
		b.WriteString("| Decided by | `" + r.Judge.String() + "` |\n")
		b.WriteString("| Decided at height | " + strconv.FormatInt(r.Decided, 10) + " |\n")
	}
	b.WriteString("\n**Why:** " + sanitize.InlineText(r.Reason) + "\n")
	if r.Note != "" {
		b.WriteString("\n**Refused because:** " + sanitize.InlineText(r.Note) + "\n")
	}
	b.WriteString("\n[Back to the faucet](" + Link + ")\n")
	return b.String()
}

// reqPath parses "req/<id>".
func reqPath(path string) (int64, bool) {
	rest, ok := strings.CutPrefix(path, "req/")
	if !ok {
		return 0, false
	}
	id, err := strconv.ParseInt(rest, 10, 64)
	if err != nil || id <= 0 {
		return 0, false
	}
	return id, true
}

// excerpt cuts to width RUNES, never bytes: slicing a multi-byte character in
// half puts invalid UTF-8 on the page, and one emoji in a reason is enough.
// It cuts before escaping, because escaping inserts backslashes and cutting an
// already-escaped string can strand a lone one that escapes the chrome after
// it.
func excerpt(s string, width int) string {
	r := []rune(s)
	if len(r) <= width+1 {
		return s
	}
	return string(r[:width]) + "…"
}

// gnot renders ugnot as GNOT with the trailing zeros of the fraction trimmed,
// so 100000000 reads as 100 and 1500000 as 1.5.
func gnot(ugnot int64) string {
	neg := ""
	if ugnot < 0 {
		neg, ugnot = "-", -ugnot
	}
	whole := strconv.FormatInt(ugnot/1_000_000, 10)
	frac := strconv.FormatInt(ugnot%1_000_000, 10)
	if frac == "0" {
		return neg + whole
	}
	for len(frac) < 6 {
		frac = "0" + frac
	}
	return neg + whole + "." + strings.TrimRight(frac, "0")
}

const (
	intro = "Somebody you trust has no GNOT and cannot use the public faucet. File a\n" +
		"request on their behalf, an approver releases it, and both halves stay on\n" +
		"this page with a reason attached. The faucet only ever spends what has been\n" +
		"sent to its own address."

	howto = "## How\n\n" +
		"`Request(to, amount, reason)` is open to anyone and moves no money.\n" +
		"`Approve(id, to, amount)` pays it, and only an approver can call it.\n\n" +
		"Send both in **one transaction**: a tm2 transaction stops at the first\n" +
		"message that fails and writes none of their state, so the ask and its\n" +
		"answer land together or not at all. Read `NextID` to address the approval,\n" +
